body.in-game.angle-c-runtime #scoreModal .sb-total{font-size:28px!important;line-height:1!important;}
body.in-game.angle-c-runtime #scoreModal :is(.sb-label,.sb-delta,.ghsb-contract,.ghsb-summary,.ghsb-nest-title){font-size:12px!important;line-height:1.15!important;}
}
/* Each score detail is a separate one-screen view; summary returns to scores. */
@media (orientation:landscape){
body.in-game.angle-c-runtime #scoreModal .gh-approved-scoreboard:has(>details[open]) > :not(details[open]){display:none!important;}
body.in-game.angle-c-runtime #scoreModal .gh-approved-scoreboard > details[open] > summary::before{content:'‹ Back to score · ';}
body.in-game.angle-c-runtime #scoreModal .gh-approved-scoreboard > details > summary{min-height:44px!important;display:flex!important;align-items:center!important;cursor:pointer;}
body.in-game.angle-c-runtime #scoreModal .ghsb-details{font-size:12px!important;line-height:1.2!important;gap:5px!important;padding:6px!important;}
body.in-game.angle-c-runtime #scoreModal .ghsb-result-line{font-size:12px!important;line-height:1.2!important;}
}

@media (orientation:landscape){
body.in-game.angle-c-runtime #ltPlays{inset:0!important;width:100vw!important;height:100dvh!important;pointer-events:none!important;}
body.in-game.angle-c-runtime #ltPlays .lt-play[data-c-seat]{position:fixed!important;left:var(--c-toss-x)!important;top:var(--c-toss-y)!important;width:var(--c-play-w)!important;height:var(--c-play-h)!important;transform:translate(-50%,-50%) scaleY(.82) rotate(var(--c-toss-angle))!important;}
body.in-game.angle-c-runtime #ltPlays .lt-play :is(.lt-order,.lt-win-stamp,.lt-roles){display:none!important;}
}

/* C navigation: retain original controls and authoritative bidding lock. */
@media (orientation:landscape){
body.in-game.angle-c-runtime .in-game-leave{width:48px!important;height:104px!important;gap:8px!important;padding:0!important;flex-direction:column!important;align-items:center!important;scale:1!important;}
body.in-game.angle-c-runtime .in-game-leave :is(#btnToggleTopOpts,#leaveReplaceBtn){width:48px!important;height:48px!important;min-width:48px!important;min-height:48px!important;flex:0 0 48px!important;margin:0!important;padding:0!important;transform:none!important;translate:none!important;scale:1!important;}
body.in-game.angle-c-runtime .in-game-leave .rail-inlay036{width:30px!important;height:30px!important;transform:none!important;opacity:1!important;}
}
/* Keep the existing leave confirmation above the landscape presentation. */
@media (orientation:landscape){
body.in-game.angle-c-runtime #confirmSheet:not(.hidden){position:fixed!important;z-index:210000!important;visibility:visible!important;pointer-events:auto!important;}
}

@media (orientation:landscape){
body.in-game.angle-c-runtime #angleCCharacters{position:absolute;inset:0;z-index:0;pointer-events:none;}
#angleCCharacters img,#angleCHolderLip,#angleCLocalAvatar{position:fixed;pointer-events:none;max-width:none;max-height:none;}
